import { PromptComposer } from "@/components/prompt-composer";

<PromptComposer
  status={status}
  onSubmit={(text) => send(text)}
  onStop={stop}
  onFilesSelected={(files) => addFiles(files)}
  toolbar={<ModeSwitcher modes={modes} />}
  maxLength={4000}
/>
